 x=src.history_frame(frame,dict(run_id=path,case_id=case,initial_state_id="S03276" if case=="P001" else "S00579",schedule_id=path,path_type=path_type));x.insert(0,"figure_id",fig);x.insert(1,"panel_id","A-F");x.insert(3,"path_label",path);x["densification_rate"]=x.rho_dot_total;x["sigma_eff_MPa"]=x.sigma_eff/1e6;return x
