 pd.DataFrame(select).to_csv(OUT/"final_case_selection.csv",index=False)
 ts=two.groupby("path_label").tail(1)[["path_label","rho","G_nm","T_C","physical_time_h"]];ts["rho_target"]=.90;ts["switch_rho_actual"]=first.rho;ts["G1_nm"]=first.G_m*1e9;ts["finite_window_C"]="875-1000";ts.to_csv(OUT/"final_twostep_summary.csv",index=False)
 available=set(heat.columns)&set(two.columns);requested=set("figure_id panel_id case_id path_label path_type physical_time_s physical_time_h T_C rho G_nm G_um phi_open_total phi_iso_total phi_closed_total pore_D50_nm pore_D90_nm rho_dot_open rho_dot_closed rho_dot_total densification_rate cumulative_open_density_gain cumulative_closed_density_gain PR_memory PR_work A_closed_available A_closed_used A_closed_recovered activity Gstar_eV sigma_eff sigma_eff_MPa tau_nuc tau_exchange tau_transport tau_cycle Gamma_migration G_dot_intrinsic G_dot_actual mechanism_mode closed_law_mode mobility_case".split());pd.DataFrame([dict(field=x,status="unavailable in source diagnostics; not fabricated") for x in sorted(requested-available)]).to_csv(OUT/"missing_history_fields.csv",index=False)
 state=dict(branch="codex/zro2-forward-final-summary-figures",source_branch="codex/zro2-forward-processing-window-prediction-figures",source_commit="255446c",model_physics_changed=False,material_fitting=False,mobility_optimization=False,broad_search_run=False,selected_trajectory_reconstruction_only=True,heating_case="P001",twostep_case="P014",twostep_strict_success=True,finite_chen_window=True,validation=False);(OUT/"run_state.json").write_text(json.dumps(state,indent=2)+"\n");print(state)
